import { Component, input, output, signal, computed, ElementRef, viewChildren, effect, AfterViewInit } from '@angular/core';

@Component({
  selector: 'exhuma-card-swipe-stack',
  standalone: true,
  template: `
    <div class="relative flex items-center justify-center min-h-[14.5rem] w-full select-none {{ customClass() }}">
